import os, sys, pty, select, signal, errno

def run(argv, cols=80, rows=25, timeout=600):
    pid, fd = pty.fork()
    if pid == 0:
        os.environ['COLUMNS']=str(cols)
        os.environ['LINES']=str(rows)
        try:
            os.execv(argv[0], argv)
        except Exception as e:
            os._exit(127)
    import fcntl, termios, struct
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b''
    while True:
        try:
            r,_,_ = select.select([fd], [], [], timeout)
        except InterruptedError:
            continue
        if not r: break
        try:
            data = os.read(fd, 65536)
        except OSError:
            break
        if not data: break
        out += data
    _, status = os.waitpid(pid, 0)
    code = os.WEXITSTATUS(status) if os.WIFEXITED(status) else -os.WTERMSIG(status)
    return out, code

if __name__ == '__main__':
    args = sys.argv[1:]
    cols = 80
    if args and args[0].startswith('--cols='):
        cols = int(args[0].split('=')[1]); args = args[1:]
    outfile = None
    if args and args[0].startswith('--out='):
        outfile = args[0].split('=',1)[1]; args = args[1:]
    out, code = run(args, cols=cols)
    if outfile:
        open(outfile,'wb').write(out)
    else:
        sys.stdout.buffer.write(out)
    sys.stderr.write("\n[EXIT=%d]\n" % code)
EOF
